{
  "title": "Q4 onboarding survey readout",
  "subtitle": "400 respondents | 78 churned (19.5%) | Executive sync | 16 Oct 2026",
  "summary": "Onboarding friction—not pricing—is the leading churn signal. Slow setup, the Salesforce integration gap, and unclear pricing account for 63 of 78 churn cases (80.8%), concentrating the near-term opportunity in faster time-to-value and clearer expectation setting.",
  "sections": [
    {
      "heading": "Top three churn drivers",
      "paragraphs": [
        "Ranked from stated reasons among churned respondents; shares use 78 churned respondents as the denominator."
      ]
    },
    {
      "heading": "Where to act",
      "bullets": [
        "Reduce setup time first: churned respondents reached a first report in 19.1 days on average versus 7.0 days for retained respondents.",
        "Set Salesforce expectations before setup and provide a clear integration path; the gap caused 21 churns, 17 of them in SMB.",
        "Clarify pricing before handoff and reinforce it in onboarding; unclear pricing caused 18 churns.",
        "Prioritize SMB: 62 of 78 churns came from SMB, where the churn rate was 28.2% (versus 11.5% mid-market and 2.0% enterprise)."
      ]
    }
  ],
  "table": {
    "columns": ["Rank", "Driver", "Churned", "Share of churn"],
    "rows": [
      ["1", "Setup took too long", "24", "30.8%"],
      ["2", "Missing Salesforce integration", "21", "26.9%"],
      ["3", "Pricing was unclear", "18", "23.1%"]
    ]
  },
  "sources_note": "Source: inputs/q4-onboarding-survey.csv (400 responses; churned=yes grouped by churn_reason; segment and days_to_first_report cuts). Context checked: memories m_mail_7f3a and m_notes_21c9. Percentages may not sum due to rounding."
}

